CREATE TABLE "c_Booking" ("id" BIGINT NOT NULL, "a_Booking_booked_at" TIMESTAMP NOT NULL, "a_Booking_status" TEXT NOT NULL, "r_TravelerBookings_source_id" BIGINT, PRIMARY KEY ("id"), CHECK ((TRUE) OR "r_TravelerBookings_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_TravelerBookings_source_id" IS NOT NULL));
CREATE TABLE "c_ItineraryItem" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_FlightSegment_flight_no" TEXT, "a_HotelStay_hotel_name" TEXT, "a_ItineraryItem_start_time" TIMESTAMP, "r_BookingItems_source_id" BIGINT, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('FlightSegment','HotelStay','ItineraryItem')), CHECK ((dtype IN ('FlightSegment')) OR "a_FlightSegment_flight_no" IS NULL), CHECK (NOT (dtype IN ('FlightSegment')) OR "a_FlightSegment_flight_no" IS NOT NULL), CHECK ((dtype IN ('HotelStay')) OR "a_HotelStay_hotel_name" IS NULL), CHECK (NOT (dtype IN ('HotelStay')) OR "a_HotelStay_hotel_name" IS NOT NULL), CHECK ((dtype IN ('FlightSegment','HotelStay','ItineraryItem')) OR "a_ItineraryItem_start_time" IS NULL), CHECK (NOT (dtype IN ('FlightSegment','HotelStay','ItineraryItem')) OR "a_ItineraryItem_start_time" IS NOT NULL), CHECK ((dtype IN ('FlightSegment','HotelStay','ItineraryItem')) OR "r_BookingItems_source_id" IS NULL), CHECK (NOT (dtype IN ('FlightSegment','HotelStay','ItineraryItem')) OR "r_BookingItems_source_id" IS NOT NULL));
CREATE TABLE "c_Payment" ("id" BIGINT NOT NULL, "a_Payment_amount" NUMERIC NOT NULL, "r_BookingPayments_source_id" BIGINT, PRIMARY KEY ("id"), CHECK ((TRUE) OR "r_BookingPayments_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_BookingPayments_source_id" IS NOT NULL));
CREATE TABLE "c_Traveler" ("id" BIGINT NOT NULL, "a_Traveler_name" TEXT NOT NULL, PRIMARY KEY ("id"));
